add('groups','Equal groups',/^(\d+) groups of (\d+) (\w+)\. (How many altogether|Which number sentence matches)\?/,(m)=>{const a=+m[1],b=+m[2],p=a*b,ms=/sentence/.test(m[4]);return fin([{t:`There are ${a} groups and ${b} ${m[3]} in each group.`,svg:unitBar(a,String(b))},{t:`Count in ${b}s: ${Array.from({length:a},(_,k)=>(k+1)*b).join(', ')}.`},{t:`${a} groups of ${b} is ${a} × ${b} = ${p}.`}],ms?`${a} × ${b} = ${p}`:p);});
add('rows','Equal rows',/in (\d+) rows with (\d+) \w+ in each row\. How many/,(m,g)=>mulFn(+m[1],+m[2],g));
add('beats','Multiplication story',/has (\d+) beats in each line\. How many beats in (\d+) lines/,(m,g)=>{const r=mulFn(+m[2],+m[1],g);r.steps.unshift({t:`${m[2]} lines with ${m[1]} beats each is ${m[2]} × ${m[1]}.`});return r;});
add('twice','Twice as many',/has (\d+) \w+\. \w+ has twice as many/,(m)=>{const a=+m[1];return fin([{t:`Twice as many means 2 times as many.`,svg:barSVG([[a,String(a)],[a,String(a)]],['#ffd166','#a0e7a0'])},{t:`2 × ${a} means ${a} + ${a}, which makes ${2*a}.`}],2*a);});
// division
const divFn=(a,b,g,unit)=>{const q=Math.floor(a/b),r=a%b;if(q<=12&&b<=12){return fin([{t:`${a} ÷ ${b}: how many ${b}s make ${a}? Think: ${b} × ? = ${a}.`},{t:`Count in ${b}s: ${Array.from({length:q},(_,k)=>(k+1)*b).join(', ')}. That is ${q} lots of ${b}.`,svg:lineSVG(0,a,Array.from({length:q},(_,k)=>[k*b,(k+1)*b,'+'+b]),[[0,'0'],[q*b,String(q*b),'#1d7fd6']].concat(r?[[a,String(a),'#e76f51']]:[]))},{t:r?`${q} × ${b} = ${q*b}, with ${r} left over.`:`${b} × ${q} = ${a}, so ${a} ÷ ${b} = ${q}.`}],null);}
 const st=[{t:`Take away big chunks of ${C(b)} until nothing is left (chunking).`}];let rem=a,tot=0;while(rem>=b){const k=[100,50,20,10,5,2,1].find(c=>c*b<=rem);st.push({t:`${k} × ${C(b)} = ${C(k*b)}. ${C(rem)} − ${C(k*b)} = ${C(rem-k*b)} left.`});rem-=k*b;tot+=k;}
 st.push({t:`Add the chunks we used: that makes ${tot}${rem?` with ${rem} left over`:''}. So ${C(a)} ÷ ${C(b)} = ${tot}.`});return fin(st,tot);};
add('div','Division',/^([\d,]+) ÷ ([\d,]+) = \?/,(m,g)=>{const a=N(m[1]),b=N(m[2]);if(a%b)return null;const r=divFn(a,b,g);r.val=a/b;return r;},(g,m)=>{const b=N(m[2]),q=Math.max(2,N(m[1])/N(m[2])+(Math.random()<.5?1:-1));return {q:`${C(b*q)} ÷ ${C(b)} = ?`,ans:C(q),wr:[C(q+1),C(q*2)]};});
add('so','Division fact',/^(\d+) × (\d+) = (\d+)\. So (\d+) ÷ (\d+) = \?/,(m)=>{const a=+m[4],b=+m[5];return fin([{t:`Division undoes multiplication.`},{t:`We know ${m[1]} × ${m[2]} = ${m[3]}. So ${a} shared into groups of ${b} gives ${a/b}.`}],a/b);});
add('share','Sharing equally',/^(\d+) (\w+) (?:make|are shared equally among) (\d+) (?:equal lines|\w+)\. How many/,(m,g)=>{const a=+m[1],b=+m[3];if(a%b)return null;const r=divFn(a,b,g);r.steps.unshift({t:`Sharing ${a} ${m[2]} equally into ${b} means ${a} ÷ ${b}.`,svg:unitBar(b,String(a/b))});r.steps.push({t:`Each one gets ${a/b}.`});r.val=a/b;return r;});
add('rem','Remainders',/^(\d+) (\w+) are packed in bags of (\d+)\. How many full bags, and how many left over\?/,(m,g)=>{const a=+m[1],b=+m[3],q=Math.floor(a/b),r=a%b;const x=divFn(a,b,g);x.steps.push({t:`${q} full bag${q>1?'s':''}, and ${r} left over.`});x.val=`${q} bags, ${r} left over`;return x;});
add('groupsof','Grouping',/has (\d+) drumsticks\. Each player needs (\d+)\. How many groups of \d+/,(m,g)=>{const r=divFn(+m[1],+m[2],g);r.val=+m[1]/+m[2];return r;});
add('repsub','Repeated subtraction',/^Start at (\d+)\. Take away (\d+) again and again until you reach 0\./,(m)=>{const a=+m[1],b=+m[2],q=a/b;const st=[];let v=a;const seq=[];while(v>0){seq.push(`${v} − ${b} = ${v-b}`);v-=b;}return fin([{t:`Take away ${b} each time and count the jumps.`,svg:lineSVG(0,a,Array.from({length:q},(_,k)=>[a-k*b,a-(k+1)*b,'−'+b]),[[0,'0'],[a,String(a)]])},{t:seq.join(', ')+'.'},{t:`We took away ${b} ${q} times.`}],q);});
// place value
const PN={ones:0,tens:1,hundreds:2,thousands:3,'ten thousands':4,'hundred thousands':5,millions:6};
add('pv','Place value',/^In ([\d,]+), what is the (total value|value|face value|place value) of the digit (\d)\?/,(m)=>{const n=N(m[1]),s=String(n),d=m[3];if(s.split(d).length!==2)return null;const p=s.length-1-s.indexOf(d),tv=+d*10**p;
 const st=[{t:`Put ${C(n)} in a place value chart. Find the digit ${d}.`,svg:pvSVG(n,p)},{t:`The ${d} is in the ${PL[p]} place.`}];
 if(m[2]==='place value')return fin(st,PL[p]);if(m[2]==='face value'){st.push({t:`The face value is just the digit itself: ${d}.`});return fin(st,d);}
 st.push({t:`Its value is ${d} ${PL[p]}: ${d} × ${C(10**p)} = ${C(tv)}.`});return fin(st,tv);});
add('tensplace','Place value',/^Which digit is in the (ones|tens|hundreds) place of (\d+)\?/,(m)=>{const n=+m[2],p=PN[m[1]];const d=Math.floor(n/10**p)%10;return fin([{t:`Put ${n} in a place value chart.`,svg:pvSVG(n,p)},{t:`The digit in the ${m[1]} place is ${d}.`}],d);});
add('expand','Expanded form',/^Which is the expanded form of ([\d,]+)\?/,(m,g,q)=>{const n=N(m[1]);const z=/(^|\+ )0( \+|$)/.test(q.c[q.a]);const parts=digs(n).map((d,i)=>d*10**i).filter(v=>v||z).reverse();return fin([{t:`Put ${C(n)} in a place value chart.`,svg:pvSVG(n,-1)},{t:`Write the value of each digit: ${parts.map(C).join(', ')} ${z?'':'(skip the zeros)'}.`},{t:`Join them with +: ${parts.map(C).join(' + ')}.`}],parts.join(' + '));});
add('compose','Place value',/^What number is ([\d ]+(?:\+ [\d ]+)+)\?/,(m)=>{const ps=m[1].split('+').map(N);const n=ps.reduce((a,b)=>a+b,0);return fin([{t:`Put each part in its place: ${ps.map(C).join(', ')}.`,svg:pvSVG(n,-1)},{t:`Read the chart: ${C(n)}.`}],n);});
add('htu','Place value',/^(\d+) hundreds, (\d+) tens and (\d+) ones make/,(m)=>{const n=+m[1]*100+ +m[2]*10+ +m[3];return fin([{t:`Put ${m[1]} in hundreds, ${m[2]} in tens, ${m[3]} in ones.`,svg:pvSVG(n,-1)},{t:`${+m[1]*100} + ${+m[2]*10} + ${m[3]} = ${n}.`}],n);});
add('showtens','Tens and ones',/^Which shows (\d\d)\?/,(m)=>{const n=+m[1];return fin([{t:`In ${n}, the ${Math.floor(n/10)} is in the tens place and the ${n%10} is in the ones place.`,svg:pvSVG(n,-1)},{t:`So ${n} is ${Math.floor(n/10)} tens and ${n%10} ones.`}],`${Math.floor(n/10)} tens and ${n%10} ones`);});
// rounding
add('round','Rounding',/^Round ([\d,]+) to the nearest (ten|hundred|thousand)\.?$/,(m)=>{const n=N(m[1]),to={ten:10,hundred:100,thousand:1000}[m[2]],lo=Math.floor(n/to)*to,hi=lo+to,r=n-lo>=to/2?hi:lo,dig=Math.floor(n/(to/10))%10;
 return fin([{t:`${C(n)} is between ${C(lo)} and ${C(hi)}.`,svg:lineSVG(lo,hi,[],[[lo,C(lo)],[lo+to/2,C(lo+to/2),'#999'],[n,C(n),'#e76f51'],[hi,C(hi)]])},{t:`Look at the digit to the right of the ${m[2]}s place: it is ${dig}. ${dig>=5?'5 or more, so round up.':'Less than 5, so round down.'}`},{t:`${C(n)} rounds to ${C(r)}.`,svg:lineSVG(lo,hi,[],[[lo,C(lo),r===lo?'#1d7fd6':null],[n,C(n),'#e76f51'],[hi,C(hi),r===hi?'#1d7fd6':null]])}],r);},(g,m)=>{const n=N(m[1]),to={ten:10,hundred:100,thousand:1000}[m[2]];let n2=n+Math.round((Math.random()-.5)*to*4);if(n2<to)n2=n+to;if(n2%to===0)n2+=Math.ceil(to/5);const r=Math.round(n2/to)*to;return {q:`Round ${C(n2)} to the nearest ${m[2]}.`,ans:C(r),wr:[C(r===Math.floor(n2/to)*to?r+to:r-to),C(n2)]};});
add('round5','Rounding to 5 cents',/Round \$([\d.]+) to the nearest 5 cents/,(m)=>{const c=Math.round(+m[1]*100),lo=Math.floor(c/5)*5,hi=lo+5,r=c-lo<hi-c?lo:hi;return fin([{t:`${M(c)} is between ${M(lo)} and ${M(hi)}.`,svg:lineSVG(lo,hi,[],[[lo,M(lo)],[c,M(c),'#e76f51'],[hi,M(hi)]])},{t:`It is ${c-lo} cent${c-lo>1?'s':''} from ${M(lo)} and ${hi-c} cent${hi-c>1?'s':''} from ${M(hi)}.`},{t:`The closer one is ${M(r)}, so round ${r>c?'up':'down'}.`}],M(r));});
// money
const amts=t=>[...t.matchAll(/\$([\d,]+(?:\.\d\d)?)|\b(\d+)c\b/g)].map(x=>x[1]!=null?Math.round(N(x[1])*100):+x[2]);
function moneyFmt(ans){return !/[$c]/.test(ans)?(c=>C(c/100)):/c$/.test(ans)?(c=>c+'c'):/\.\d\d/.test(ans)?M:(c=>'$'+C(c/100));}
function countUp(cost,paid,f){const st=[],j=[];let v=cost;const stops=[];if(v%100){const n=Math.ceil(v/100)*100;if(n<=paid){stops.push(n);}}let cur=stops.length?stops[0]:v;if(cur%1000&&Math.ceil(cur/1000)*1000<=paid&&Math.ceil(cur/1000)*1000!==cur&&paid-cur>1000){stops.push(Math.ceil(cur/1000)*1000);}else if(cur%500&&paid>=500&&Math.ceil(cur/500)*500<=paid&&Math.ceil(cur/500)*500!==cur){stops.push(Math.ceil(cur/500)*500);}if(stops[stops.length-1]!==paid)stops.push(paid);
 let prev=cost;stops.forEach(s=>{if(s>prev){j.push([prev,s,'+'+f(s-prev)]);prev=s;}});const txt=j.map(x=>`${f(x[0])} → ${f(x[1])} is ${x[2].slice(1)}`).join('; ');
 st.push({t:`Count up from the cost, ${f(cost)}, to the money paid, ${f(paid)}, like a shopkeeper.`,svg:lineSVG(cost,paid,j,[[cost,f(cost)],[paid,f(paid)]])});st.push({t:txt+'.'});
 if(j.length>1)st.push({t:`Add the jumps: ${j.map(x=>x[2].slice(1)).join(' + ')} = ${f(paid-cost)}.`});return st;}
function itemsCost(t){// returns {cost, steps} for "N ... at $p each" plus single items
 const st=[];let cost=0,rest=t;const each=[...t.matchAll(/(\d+|one|two|three|four|five|six|seven|eight|nine|ten)\s+[\w\s-]*? (?:at|for) \$([\d.]+) each/gi)];
 each.forEach(e=>{const n=WN[e[1].toLowerCase()]||+e[1],p=Math.round(+e[2]*100);cost+=n*p;st.push({k:'m',n,p});rest=rest.replace(e[0],'');});return {cost,rest,mul:st};}
add('change','Money: change',/(?:How much (?:change|money is left|will be left)|How much change do you get)/,(m,g,q)=>{const t=strip(q.q),A=q.c[q.a],fv=moneyFmt(A),f=/[$c]/.test(A)?fv:(c=>'$'+C(c/100));let paid=null,mm;
 if((mm=t.match(/pa(?:y|ys) (?:with )?(?:a |an )?(\$[\d,.]+|\d+c)/i))||(mm=t.match(/has (\$[\d,.]+)/))||(mm=t.match(/You have (\$[\d,.]+)/)))paid=money(mm[1].replace(/\.$/,''));if(paid==null)return null;
 const ic=itemsCost(t.replace(mm[0],' '));let cost=ic.cost;const others=amts(ic.rest);cost+=others.reduce((a,b)=>a+b,0);if(!cost)return null;const st=[];
 if(ic.mul.length)ic.mul.forEach(x=>st.push({t:`${x.n} × ${f(x.p)} = ${f(x.n*x.p)}.`}));const parts=ic.mul.map(x=>x.n*x.p).concat(others);
 if(parts.length>1){const r=addSteps(parts,true,g);st.push({t:`Add the costs: ${parts.map(f).join(' + ')} = ${f(cost)}.`,svg:colSVG({rows:parts.map(x=>pad(digs(x),3).map(String)),op:'+',res:pad(digs(cost),3).map(String),dp:true})});}
 if(ic.mul.length&&parts.length===1)st[0].t='Cost: '+st[0].t;return fin(st.concat(countUp(cost,paid,f)),fv(paid-cost));});
add('total','Money: total cost',/(?:What is the total(?: cost)?\?|What do (\d+) \w+ cost\?|How much do they pay altogether\?)/,(m,g,q)=>{const t=strip(q.q),A=q.c[q.a],f=moneyFmt(A);const st=[];let parts=[];
 let mm;if((mm=t.match(/costs \$([\d.]+)\. What do (\d+) \w+ cost/))){const p=Math.round(+mm[1]*100),n=+mm[2];const r=mulFn(n,p,g);return fin([{t:`${n} bags at ${f(p)} each is ${n} × ${f(p)}.`},{t:`Work in cents: ${n} × ${C(p)} cents.`}].concat(r.steps.slice(0)).concat([{t:`${C(n*p)} cents = ${f(n*p)}.`}]),f(n*p));}
 if((mm=t.match(/^(\d+) \w+ each pay \$(\d+)/))||(mm=t.match(/^(\w+) bunches of bananas cost \$(\d+) each/))||(mm=t.match(/buys (\d+) [\w-]+(?: [\w-]+)* at \$(\d+) each/))){const n=WN[String(mm[1]).toLowerCase()]||+mm[1],p=+mm[2];const r=mulFn(n,p,g);return fin([{t:`${n} lots of $${p} is ${n} × $${p}.`}].concat(r.steps).concat([{t:`So the total is $${C(n*p)}.`}]),'$'+C(n*p));}
 parts=amts(t);if(parts.length<2)return null;const tot=parts.reduce((a,b)=>a+b,0);
 if(parts.every(x=>x%100===0)&&tot<=2000&&!/\.\d\d/.test(A)){const ds=parts.map(x=>x/100);const r=addFn(ds,g);r.steps.unshift({t:`Add the prices: ${ds.map(x=>'$'+x).join(' + ')}.`});r.val='$'+C(tot/100);return r;}
 const r=addSteps(parts,true,g);return fin([{t:`Write the prices in a column, lining up the decimal points: ${parts.map(f).join(', ')}.`,svg:colSVG({rows:parts.map(x=>pad(digs(x),3).map(String)),op:'+',res:[],dp:true})}].concat(r.steps),f(tot));});
add('profit','Profit and loss',/(?:Cost price \$(\d+)\. Selling price \$(\d+)\.|for \$(\d+)(?: \(cost price\))? and sells it for \$(\d+))/,(m,g,q)=>{const cp=+(m[1]||m[3]),sp=+(m[2]||m[4]),pr=sp>cp,d=Math.abs(sp-cp),yn=/profit or a loss\?$/.test(strip(q.q));
 const st=[{t:`Cost price (what the seller paid) = $${cp}. Selling price (what they sold it for) = $${sp}.`,svg:barSVG(pr?[[cp,'$'+cp+' cost'],[d,'+$'+d]]:[[sp,'$'+sp+' sold'],[d,'−$'+d]],pr?['#ffd166','#a0e7a0']:['#ffd166','#f4a3a3'])},{t:`The selling price is ${pr?'MORE':'LESS'} than the cost price, so it is a ${pr?'profit':'loss'}.`}];
 if(!yn)st.push({t:`$${Math.max(cp,sp)} − $${Math.min(cp,sp)} = $${d}.`});return fin(st,yn?(pr?'profit':'loss'):`${pr?'profit':'loss'} of $${d}`);});
add('sellprice','Selling price',/pays \$(\d+) for a \w+ and wants a profit of \$(\d+)/,(m)=>{const a=+m[1],b=+m[2];return fin([{t:`Selling price = cost price + profit.`,svg:barSVG([[a,'$'+a+' cost'],[b,'+$'+b]],['#ffd166','#a0e7a0'])},{t:`$${a} + $${b} = $${a+b}.`}],'$'+(a+b));});
// percent
const pctSteps=(p,n,f)=>{f=f||(x=>C(x));const st=[];if(p%10===0||p===25||p===75||p===5||p===15){if(p===50)return [{t:`50% means half. Half of ${f(n)} is ${f(n)} ÷ 2 = ${f(n/2)}.`,svg:barSVG([[1,'50%'],[1,'50%']],['#ffd166','#eef3ff'])}];if(p===25||p===75){st.push({t:`25% means a quarter. ${f(n)} ÷ 4 = ${f(n/4)}.`,svg:barSVG([[1,'25%'],[1,'25%'],[1,'25%'],[1,'25%']],['#ffd166','#eef3ff'])});if(p===75)st.push({t:`75% is 3 quarters: 3 × ${f(n/4)} = ${f(3*n/4)}.`});return st;}
  const t=n/10;st.push({t:`Find 10% first: 10% of ${f(n)} is ${f(n)} ÷ 10 = ${f(t)}.`,svg:unitBar(10,'10%')});if(p===5){st.push({t:`5% is half of 10%: ${f(t)} ÷ 2 = ${f(t/2)}.`});return st;}if(p===15){st.push({t:`5% is half of 10%: ${f(t/2)}. 15% = 10% + 5% = ${f(t)} + ${f(t/2)} = ${f(1.5*t)}.`});return st;}if(p!==10)st.push({t:`${p}% is ${p/10} lots of 10%: ${p/10} × ${f(t)} = ${f(t*p/10)}.`});return st;}
 st.push({t:`Find 1% first: ${f(n)} ÷ 100 = ${f(n/100)}.`});st.push({t:`${p}% = ${p} × ${f(n/100)} = ${f(n*p/100)}.`});return st;};
add('pct','Percent of an amount',/^What is (\d+)% of (\d+)\?/,(m)=>{const p=+m[1],n=+m[2];if(p>100){const st=[{t:`${p}% is more than 100%, so the answer is more than ${n}.`},{t:`100% of ${n} is ${n}.`}].concat(pctSteps(p-100,n).map(x=>({t:x.t.replace(/^/,'Now the extra '+(p-100)+'%: ')})));st.push({t:`Add: ${n} + ${n*(p-100)/100} = ${n*p/100}.`});return fin(st,n*p/100);}return fin(pctSteps(p,n),n*p/100);});
add('pctwalk','Percent of an amount',/^About (\d+)% of the (\d+) children/,(m)=>{const p=+m[1],n=+m[2];return fin(pctSteps(p,n),n*p/100);});
add('pctest','Estimating percent',/^Estimate (\d+)% of (\d+)\./,(m)=>{const p=+m[1],n=+m[2],nn=[40,80,120,200,400].find(x=>Math.abs(x-n)<=6);if(!nn)return null;return fin([{t:`Round ${n} to a friendly number close by: ${nn}.`}].concat(pctSteps(p,nn)).concat([{t:`So ${p}% of ${n} is about ${nn*p/100}.`}]),nn*p/100);});
add('pctof','Percent of another',/scored (\d+) out of (\d+)/,(m)=>{const a=+m[1],b=+m[2],k=100/b;return fin([{t:`Write it as a fraction: ${a}/${b}.`},{t:`Make the bottom 100: multiply top and bottom by ${k}. ${a}/${b} = ${a*k}/100.`},{t:`${a*k} out of 100 is ${a*k}%.`}],`${a*k}%`);});
add('disc','Discount',/costs \$(\d+(?:\.\d\d)?)\.? (?:The shop gives|With a) (\d+)% discount(?:, how much money do you save\?|\. What is the sale price\?)/,(m,g,q)=>{const pr=Math.round(+m[1]*100),p=+m[2],d=pr*p/100,save=/save/.test(q.q);const st=pctSteps(p,pr/100,x=>M(x*100));st.unshift({t:`The discount is ${p}% of ${M(pr)}.`});if(save)return fin(st,M(d));st.push({t:`Sale price = price − discount = ${M(pr)} − ${M(d)} = ${M(pr-d)}.`});return fin(st,M(pr-d));});
add('tax','Tax',/costs \$([\d.,]+) before tax\. A pretend tax of (\d+)% is added/,(m)=>{const pr=Math.round(N(m[1])*100),p=+m[2],t=pr*p/100;const st=pctSteps(p,pr/100,x=>M(x*100));st.unshift({t:`The tax is ${p}% of ${M(pr)}.`});st.push({t:`Total = price + tax = ${M(pr)} + ${M(t)} = ${M(pr+t)}.`});return fin(st,M(pr+t));});
add('interest','Simple interest',/saves \$([\d.,]+) in a credit union at (\d+)% simple interest per year\. How much interest does she earn in (\d+) years?/,(m)=>{const P=Math.round(N(m[1])*100),r=+m[2],y=+m[3],i1=P*r/100;const st=[{t:`Interest for one year is ${r}% of ${M(P)}.`},{t:`1% of ${M(P)} is ${M(P/100)}, so ${r}% is ${r} × ${M(P/100)} = ${M(i1)}.`}];if(y>1)st.push({t:`For ${y} years: ${y} × ${M(i1)} = ${M(i1*y)}.`});return fin(st,M(i1*y));});
// fractions
add('fracadd','Adding and subtracting fractions',/^((?:\d+\/\d+)(?: [+−] \d+\/\d+)+) = \?( \((?:give the )?simplest form\))?/,(m)=>{const terms=[...m[1].matchAll(/([+−]?) ?(\d+)\/(\d+)/g)].map(x=>({s:x[1]==='−'?-1:1,n:+x[2],d:+x[3]}));const L=Math.max(...terms.map(t=>t.d));if(terms.some(t=>L%t.d))return null;const simp=!!m[2];
 const st=[];const conv=terms.filter(t=>t.d!==L);if(conv.length)conv.forEach(t=>st.push({t:`Change ${t.n}/${t.d} to ${L}ths: multiply top and bottom by ${L/t.d}. ${t.n}/${t.d} = ${t.n*L/t.d}/${L}.`}));else st.push({t:`The bottom numbers are the same (${L}), so just ${terms.some(t=>t.s<0)?'subtract':'add'} the top numbers.`});
 const nums=terms.map(t=>t.s*t.n*L/t.d),tot=nums.reduce((a,b)=>a+b,0);if(tot<=0)return null;st.push({t:`${nums.map((x,i)=>(i?(x<0?' − ':' + '):'')+Math.abs(x)+'/'+L).join('')} = ${tot}/${L}.`,svg:unitBar(Math.min(L,24)===L?L:L,'',null).replace(/fill="#ffd166"/g,'fill="#eef3ff"')});
 const res=fmtF(tot,L,simp,simp);if(simp&&res!==`${tot}/${L}`){const g=gcd(tot,L);st.push({t:g>1?`Simplify: divide top and bottom by ${g}: ${tot/g}/${L/g}${tot/g>L/g?` = ${res}`:''}.`:`${tot}/${L} = ${res}.`});}
 st[st.length-(simp&&res!==`${tot}/${L}`?2:1)].svg=fracBar(L,tot);return fin(st,res);});
function fracBar(d,n){const W=500,full=Math.ceil(n/d)||1;let s='';for(let b=0;b<full;b++)for(let i=0;i<d;i++){const w=W/d;s+=`<rect x="${10+i*w}" y="${10+b*44}" width="${w}" height="36" fill="${b*d+i<n?'#6a4cdf':'#fff'}" stroke="#333"/>`;}s+=T(260,full*44+26,`${n} of the ${d} parts${full>1?' (more than one whole)':''}`,{fs:16});return svg(520,full*44+36,s,'fraction bar');}
add('fracstory','Adding fractions',/drank (\d+)\/(\d+) of the juice\. \w+ drank (\d+)\/(\d+)\. How much/,(m)=>{const a=+m[1],d=+m[2],b=+m[3];if(+m[4]!==d)return null;return fin([{t:`Both are ${d}ths, so add the top numbers.`},{t:`${a}/${d} + ${b}/${d} = ${a+b}/${d}.`,svg:fracBar(d,a+b)}],`${a+b}/${d}`);});
add('fracof','Fraction of an amount',/(?:What is 1\/(\d+) of (\d+)\?|There are (\d+) \w+\. What is 1\/(\d+) of them\?)/,(m)=>{const d=+(m[1]||m[4]),n=+(m[2]||m[3]);if(n%d)return null;return fin([{t:`1/${d} means share into ${d} equal parts.`,svg:unitBar(d,String(n/d))},{t:`${n} ÷ ${d} = ${n/d}. So 1/${d} of ${n} is ${n/d}.`}],n/d);});
