add('mixed','Mixed numbers',/^Write (\d+)\/(\d+) as a mixed number\./,(m)=>{const a=+m[1],b=+m[2];return fin([{t:`How many whole ${b}s fit in ${a}? ${Math.floor(a/b)} lots of ${b} make ${Math.floor(a/b)*b}, with ${a%b} left over.`,svg:fracBar(b,a)},{t:`So ${a}/${b} = ${Math.floor(a/b)} wholes and ${a%b}/${b} left: ${Math.floor(a/b)} ${a%b}/${b}.`}],`${Math.floor(a/b)} ${a%b}/${b}`);});
add('fdp','Fractions, decimals and percents',/^Write ([\d./%]+) as an? (fraction(?: in simplest form)?|decimal|percent)\.$/,(m)=>{const s=m[1],to=m[2];let num,den;if(/%$/.test(s)){num=+s.slice(0,-1);den=100;}else if(s.includes('/')){[num,den]=s.split('/').map(Number);}else{const dp=(s.split('.')[1]||'').length;den=10**dp;num=Math.round(+s*den);}
 const st=[];const v100=num*100/den;if(v100%1)return null;
 if(/%$/.test(s))st.push({t:`Percent means out of 100: ${s} = ${num}/100.`});else if(s.includes('/'))st.push({t:100%den===0?`Make the bottom 100: multiply top and bottom by ${100/den}. ${num}/${den} = ${v100}/100.`:`${num}/${den} = ${v100}/100.`});else st.push({t:`${s} = ${num}/${den}${den!==100?` = ${v100}/100`:''}.`});
 let res;if(to==='percent'){res=`${v100}%`;st.push({t:`${v100}/100 = ${v100}%.`,svg:hund(v100)});}else if(to==='decimal'){res=String(v100/100);st.push({t:`${v100}/100 = ${v100/100} (${v100} hundredths).`,svg:hund(v100)});}else{const g=gcd(v100,100);res=fmtF(v100,100,true,false);st.push({t:g>1?`Simplify ${v100}/100: divide top and bottom by ${g} to get ${res}.`:`${v100}/100 cannot be simplified.`,svg:hund(v100)});}
 return fin(st,res);});
