add('rsimp','Simplifying a ratio',/There are (\d+) ([\w ]+?) and (\d+) ([\w ]+?)\. What is the ratio of .+ in simplest form\?/,(m)=>{const a=+m[1],b=+m[3],g=gcd(a,b);return fin([{t:`Write the ratio in order: ${a} : ${b}.`},{t:`Find the highest number that divides both: ${g}.`},{t:`${a} ÷ ${g} = ${a/g} and ${b} ÷ ${g} = ${b/g}. So the ratio is ${a/g} : ${b/g}.`,svg:barSVG([...Array(a/g).fill([1,'']),...Array(b/g).fill([1,''])].map(x=>x.slice()),[...Array(a/g).fill('#ffd166'),...Array(b/g).fill('#a0e7a0')])}],`${a/g} : ${b/g}`);});
