// time
const pt=s=>{s=s.trim();let m=s.match(/^(\d{1,2}):(\d\d)(?: ?([ap])m)?$/);if(m){let h=+m[1];if(m[3]==='p'&&h<12)h+=12;if(m[3]==='a'&&h===12)h=0;return h*60+ +m[2];}m=s.match(/^(\d+) o'clock$/);return m?+m[1]*60:null;};
const pdur=s=>{const m=s.match(/^(?:(\d+) (?:h|hours?))?\s*(?:(\d+) (?:min|minutes))?$/);return m&&(m[1]||m[2])?(+m[1]||0)*60+(+m[2]||0):null;};
