add('arrive','Elapsed time',/(?:leaves|starts) (?:\w+ )?at ([\d:]+|\d+ o'clock)\. The trip takes ([\dhmin ]+?)(?: \(pretend timetable\))?\. What time does it arrive\?|The boat leaves at (\d+ o'clock) and the trip takes (\d+) hour\. What time does it arrive/,(m,g,q)=>{const st0=m[1]||m[3],d=m[2]?pdur(m[2].trim()):+m[4]*60,s=pt(st0);if(s==null||d==null)return null;const e=s+d,f=x=>tstr(x,st0);const j=[];let v=s;const h=Math.floor(d/60);if(h){j.push([v,v+h*60,h+' h']);v+=h*60;}if(d%60)j.push([v,e,(d%60)+' min']);
 return fin([{t:`Start at ${f(s)} and add ${durTxt(d,true)}.`,svg:clockLine(s,e,j)}].concat(j.map(x=>({t:`${f(x[0])} + ${x[2].replace(' h',x[2]==='1 h'?' hour':' hours').replace(' min',' minutes')} = ${f(x[1])}.`}))),f(e));});
add('backward','Working backward with time',/must be at school by (\d\d:\d\d)\. The walk takes (\d+) minutes\./,(m)=>{const e=pt(m[1]),d=+m[2],s=e-d;const j=[];let v=e;if(v%60&&v%60<d){j.push([v,Math.floor(v/60)*60,'−'+(v%60)+' min']);v=Math.floor(v/60)*60;}j.push([v,s,'−'+(v-s)+' min']);
 return fin([{t:`Work backward: start at ${m[1]} and take away ${d} minutes.`,svg:clockLine(s,e,j.map(x=>[x[1],x[0],x[2]]))}].concat(j.map(x=>({t:`${hh(x[0])} − ${x[2].slice(1).replace('min','minutes')} = ${hh(x[1])}.`}))),hh(s));});
add('to24','24-hour time',/^Write (\d{1,2}):(\d\d) ([ap])m in 24-hour time\./,(m)=>{const h=+m[1],mi=+m[2],pm=m[3]==='p',H=pm?(h===12?12:h+12):(h===12?0:h);return fin([{t:pm?(h===12?'12 pm is midday, so the hour stays 12.':`pm times after midday: add 12 to the hour. ${h} + 12 = ${H}.`):(h===12?'12 am is midnight, so the hour is 00.':`am times keep the same hour, with two digits: ${String(H).padStart(2,'0')}.`)},{t:`So ${m[1]}:${m[2]} ${m[3]}m is ${hh(H*60+mi)}.`}],hh(H*60+mi));});
