// words and figures
const UNITS={zero:0,one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,eleven:11,twelve:12,thirteen:13,fourteen:14,fifteen:15,sixteen:16,seventeen:17,eighteen:18,nineteen:19,twenty:20,thirty:30,forty:40,fifty:50,sixty:60,seventy:70,eighty:80,ninety:90};
function parseWords(t){const w=t.toLowerCase().replace(/-/g,' ').split(/\s+/).filter(x=>x&&x!=='and');let tot=0,cur=0,groups=[];for(const x of w){if(x in UNITS)cur+=UNITS[x];else if(x==='hundred')cur*=100;else if(x==='thousand'||x==='million'){groups.push([cur,x]);tot+=cur*(x==='million'?1e6:1e3);cur=0;}else return null;}groups.push([cur,'']);return {n:tot+cur,groups};}
const w999=(n,and)=>{const h=Math.floor(n/100),r=n%100,p=[];if(h)p.push(ONES[h]+' hundred');if(r)p.push((h||and?'and ':'')+w99(r));return p.join(' ');};
function toWords(n){if(n===0)return 'zero';const m=Math.floor(n/1e6),th=Math.floor(n/1000)%1000,r=n%1000;return [m?w999(m)+' million':'',th?w999(th)+' thousand':'',r?w999(r,(m||th)&&r<100):''].filter(Boolean).join(' ');}
add('w2n','Words to figures',/^Write "?([a-z -]+?)(?: dollars)?"? (?:in figures|in numerals|as a number|in numbers)\.$/,(m,g,q)=>{const P=parseWords(m[1]);if(!P)return null;const dol=/dollars/.test(q.q),n=P.n;const st=[{t:`Split the words into groups: ${P.groups.filter(x=>x[0]||x[1]).map(x=>x[1]?`"${toWords(x[0])} ${x[1]}"`:`"${toWords(x[0])}"`).join(', ')}.`}];
 P.groups.forEach(([v,u])=>{if(v)st.push({t:u?`${toWords(v)} ${u} = ${C(v*(u==='million'?1e6:1e3))}.`:`${toWords(v)} = ${v}.`});});st.push({t:`Put them together in a place value chart${P.groups.some(x=>x[1]&&!x[0])?'':''}: ${C(n)}. Use 0 for any empty place.`,svg:pvSVG(n,-1)});return fin(st,dol?`$${C(n)}.00`:(n>=1000&&/,/.test(q.c[q.a])?C(n):String(n)));});
add('n2w','Figures to words',/^(?:Which words say ([\d,]+)\?|How do we write ([\d,]+) in words\?)/,(m)=>{const n=N(m[1]||m[2]),m6=Math.floor(n/1e6),th=Math.floor(n/1000)%1000,r=n%1000;const st=[{t:`Split ${C(n)} into groups of three digits from the right: ${C(n)}.`,svg:pvSVG(n,-1)}];
 if(m6)st.push({t:`${m6} million: "${w999(m6)} million".`});if(th)st.push({t:`${th} thousand: "${w999(th)} thousand".`});if(r)st.push({t:`${r}: "${w999(r,(m6||th)&&r<100)}".`});st.push({t:`Put them together: ${toWords(n)}.`});return fin(st,toWords(n));});
