add('count$','Counting money',/^How much money is this\?/,(m,g,q)=>{const lab=(q.svg||'').match(/aria-label="money: ([^"]+)"/);if(!lab)return null;const it=lab[1].split(/,\s*/).map(x=>x.trim()).filter(Boolean),vs=it.map(VAL).sort((a,b)=>b-a);if(vs.some(isNaN))return null;const A=q.c[q.a],f=moneyFmt(A);let run=0;const tot=vs.reduce((a,b)=>a+b,0);
 const cum=[];vs.forEach((v,k)=>cum.push((cum[k-1]||0)+v));const jm=vs.map((v,k)=>[k?cum[k-1]:0,cum[k],'+'+f(v)]);const st=[{t:'Start with the biggest one and count on.'},{t:vs.map(f).join(', ')+' → count on: '+cum.map(f).join(', ')+'.',svg:lineSVG(0,tot,jm,[[0,'0'],[tot,f(tot),'#1d7fd6']])},{t:'Altogether: '+f(tot)+'.'}];return fin(st,f(tot));});
